import 'dart:convert';
import 'dart:ui' show Offset;

import 'package:flutter/services.dart' show AssetBundle;

/// Offline Nepal basemap loaded from the GeoJSON assets bundled with the app.
///
/// The files are generated by `scripts/build_map_assets.py` from
/// geoJSON-Nepal (MIT). Coordinates are stored as `Offset(lon, lat)`.
class NepalMapData {
  const NepalMapData({required this.provinces, required this.headquarters});

  /// One entry per province polygon; each polygon is a list of rings.
  final List<List<List<Offset>>> provinces;

  /// District headquarters as raw `Feature` maps (geometry + name).
  final List<Map<String, dynamic>> headquarters;

  static const String statesAsset = 'assets/nepal_states.geojson';
  static const String headquartersAsset = 'assets/nepal_hq.geojson';

  static Future<NepalMapData> load(AssetBundle bundle) async {
    final states = json.decode(await bundle.loadString(statesAsset));
    final headquarters = json.decode(await bundle.loadString(headquartersAsset));
    return NepalMapData.parse(states, headquarters);
  }

  factory NepalMapData.parse(dynamic states, dynamic headquarters) {
    return NepalMapData(
      provinces: _provincesFrom(states),
      headquarters: _featuresFrom(headquarters),
    );
  }

  static List<List<List<Offset>>> _provincesFrom(dynamic geojson) {
    final provinces = <List<List<Offset>>>[];
    for (final feature in _featuresFrom(geojson)) {
      final geometry = feature['geometry'];
      if (geometry is! Map) continue;
      final coordinates = geometry['coordinates'];
      if (coordinates is! List) continue;

      switch (geometry['type']) {
        case 'Polygon':
          provinces.add(_ringsFrom(coordinates));
        case 'MultiPolygon':
          for (final polygon in coordinates) {
            if (polygon is List) provinces.add(_ringsFrom(polygon));
          }
      }
    }
    return provinces;
  }

  static List<Map<String, dynamic>> _featuresFrom(dynamic geojson) {
    if (geojson is! Map) return [];
    final features = geojson['features'];
    if (features is! List) return [];
    return features.whereType<Map>().map((f) => f.cast<String, dynamic>()).toList();
  }

  static List<List<Offset>> _ringsFrom(List polygon) {
    final rings = <List<Offset>>[];
    for (final ring in polygon) {
      if (ring is! List) continue;
      final points = <Offset>[];
      for (final pair in ring) {
        if (pair is! List || pair.length < 2) continue;
        final lon = _asDouble(pair[0]);
        final lat = _asDouble(pair[1]);
        if (lon == null || lat == null) continue;
        points.add(Offset(lon, lat));
      }
      if (points.isNotEmpty) rings.add(points);
    }
    return rings;
  }

  static double? _asDouble(dynamic value) => value is num ? value.toDouble() : null;
}
